// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address lrtConfig, bool shouldPause) public {
        vm.assume(lrtConfig != address(0));
        // Setup a minimal LRTConfig proxy to satisfy initialization and role checks
        // Deploy a mock that allows the admin role to the test contract itself
        MockLRTConfig mockConfig = new MockLRTConfig();
        mockConfig.grantAdmin(address(this));
        // Initialize C with the mock config address
        c.initialize(address(mockConfig));
        // Set the mapping so that the test contract has MANAGER role
        mockConfig.setHasRole(LRTConstants.MANAGER, address(this), true);

        bool pausedBefore = c.paused();

        // If we decide to pause, do it; otherwise leave it unpaused
        if (shouldPause) {
            vm.prank(address(this));
            c.pause();

            // After pause, paused() must return true
            bool pausedAfter = c.paused();
            assertTrue(pausedAfter);
        } else {
            // After not pausing, paused() must return false (initial state)
            bool pausedAfter = c.paused();
            assertTrue(pausedAfter == false);
        }
    }
}

contract MockLRTConfig {
    mapping(bytes32 => mapping(address => bool)) public roles;
    mapping(address => bool) public supportedAssets;
    mapping(address => uint256) public depositLimits;

    function grantAdmin(address account) public {
        roles[bytes32(0x00)][account] = true;
    }

    function setHasRole(bytes32 role, address account, bool granted) public {
        roles[role][account] = granted;
    }

    function hasRole(bytes32 role, address account) public view returns (bool) {
        return roles[role][account];
    }

    function isSupportedAsset(address asset) public view returns (bool) {
        return supportedAssets[asset];
    }

    function depositLimitByAsset(address asset) public view returns (uint256) {
        return depositLimits[asset];
    }

    function rsETH() public view returns (address) {
        return address(0);
    }

    function getContract(bytes32 id) public view returns (address) {
        return address(0);
    }
}

library LRTConstants {
    bytes32 public constant R_ETH_TOKEN = keccak256("R_ETH_TOKEN");
    bytes32 public constant ST_ETH_TOKEN = keccak256("ST_ETH_TOKEN");
    bytes32 public constant CB_ETH_TOKEN = keccak256("CB_ETH_TOKEN");
    bytes32 public constant LRT_ORACLE = keccak256("LRT_ORACLE");
    bytes32 public constant LRT_DEPOSIT_POOL = keccak256("LRT_DEPOSIT_POOL");
    bytes32 public constant EIGEN_STRATEGY_MANAGER = keccak256("EIGEN_STRATEGY_MANAGER");
    bytes32 public constant MANAGER = keccak256("MANAGER");
}

