pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool shouldPause) public {
        // Fuzz whether we pause or not
        // Deploy and initialize with a mock config address (any non-zero contract will do)
        vm.etch(address(this), hex"00");
        c.initialize(address(this));

        if (shouldPause) {
            vm.startPrank(address(this));
            c.unpause(); // ensure unpaused first
            c.pause();
            vm.stopPrank();
        } else {
            vm.startPrank(address(this));
            c.unpause();
            vm.stopPrank();
        }

        bool isPaused = c.paused();
        assertTrue(isPaused == shouldPause);
    }
}

