pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address lrtConfigAddr, address manager) public {
        vm.assume(lrtConfigAddr != address(0));
        vm.assume(manager != address(0));
        vm.assume(lrtConfigAddr.code.length > 0);

        // Setup: initialize with a minimal LRTConfig mock that gives manager role
        vm.etch(lrtConfigAddr, hex"58600080fd"); // minimal revert, overridden by mock
        c.initialize(lrtConfigAddr);

        // Grant MANAGER role to manager via a mock
        bytes memory managerRoleData = abi.encodeWithSignature("hasRole(bytes32,address)", keccak256("MANAGER"), manager);
        vm.mockCall(lrtConfigAddr, managerRoleData, abi.encode(true));

        // Fuzz: pause the contract
        vm.prank(manager);
        c.pause();

        // Assert: paused() must return true after pause()
        bool ok;
        try c.paused() returns (bool p) {
            ok = p;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

