pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool triggerPause, bool triggerUnpause) public {
        // Initialize c with a valid lrtConfig address to allow pause/unpause by admin
        // We deploy a minimal config that grants DEFAULT_ADMIN_ROLE to address(this)
        // to call pause/unpause, but the fuzzer decides whether to call them.
        // Because paused() only depends on _paused, we simply need to drive the contract
        // to some state and compare paused() with the expected internal boolean.
        // Since we cannot read private _paused, we drive through the public pause/unpause 
        // and assert that paused() always matches the last commanded state.
        // To avoid dependency on LRTConfig, we initialize with a mock that returns true for admin role.
        MockLRTConfig config = new MockLRTConfig();
        c.initialize(address(config));
        bool expectedPaused = false;
        assertEq(c.paused(), expectedPaused, "initial");

        if (triggerPause) {
            vm.prank(address(this));
            c.pause();
            expectedPaused = true;
        }
        if (triggerUnpause) {
            vm.prank(address(this));
            c.unpause();
            expectedPaused = false;
        }
        // The property: paused() must equal the correct state after pause/unpause commands.
        assertEq(c.paused(), expectedPaused, "paused mismatch");
    }
}

contract MockLRTConfig {
    function hasRole(bytes32 role, address account) external view returns (bool) {
        // DEFAULT_ADMIN_ROLE is bytes32(0)
        return role == bytes32(0) || role == keccak256("MANAGER");
    }
    function isSupportedAsset(address) external pure returns (bool) { return false; }
}

