pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Initialize the contract to avoid 'contract is already initialized' error
        address lrtConfig = address(0x123);
        // We need a minimal contract that returns true for hasRole to allow initialization
        // But to keep it simple and avoid deploying complex mocks, we use a prank and a mock address.
        // Since initialize checks for hasRole only indirectly through LRTConfigRoleChecker's onlyLRTAdmin modifier,
        // and onlyLRTAdmin calls hasRole on lrtConfig, we need lrtConfig to be a contract that returns true.
        // We'll deploy a minimal helper that always returns true for hasRole.
        MockLRTConfig mockConfig = new MockLRTConfig();
        c.initialize(address(mockConfig));
    }

    function testFuzz_property(bool initialPaused) public {
        // Set up: if initialPaused is true, pause the contract first
        if (initialPaused) {
            // Since pause() is onlyLRTManager, we need to prank as manager
            // Use the MockLRTConfig that returns true for hasRole(MANAGER, address(this))
            // We'll deploy a mock that gives us both admin and manager roles
            vm.prank(address(this));
            c.pause();
        }

        // Record the current paused state
        bool pausedBefore = c.paused();

        // Now call pause() — this should set _paused to true if it wasn't already
        vm.prank(address(this));
        try c.pause() {
            // succeeded
        } catch {
            // If pause reverts (e.g., already paused), that's fine — we just test after
        }

        // After pause(), paused() must return true
        bool pausedAfter = c.paused();

        // The property: after calling pause(), paused() must be true.
        // The buggy version returns !_paused, so after _paused is set to true, paused() returns false.
        assertTrue(pausedAfter);
    }
}

