pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool shouldPause) public {
        // Initialize the contract to allow pause/unpause (paused starts false)
        address dummyConfig = address(0x1);
        // Deploy a minimal LRTConfig mock that grants the manager role
        vm.etch(dummyConfig, hex"33600055600c8060106000396000f3fe60003660003760003660002060005260206000f300"); // minimal bytecode to avoid revert on call
        c.initialize(dummyConfig);
        if (shouldPause) {
            // To pause, we need to be the manager. We are the manager because we initialized and set the config.
            // But the role check requires the config to have MANAGER role. We can't easily fake it, so we use vm.prank
            // and assume the config address is the caller. Actually, onlyLRTManager checks hasRole on lrtConfig address.
            // A minimal mock is needed. Instead, we can use the fact that C's initialize sets lrtConfig.
            // Since we cannot easily mock access control, we focus on the property that paused() returns the same as the
            // state after _pause/_unpause calls, but those are protected. The difference is directly on paused().
            // However, the property must hold regardless. Let's use the internal _paused access pattern:
            // We cannot read _paused directly. But we can observe the effect of whenNotPaused modifier.
            // A better approach: The only unconditional view of state is paused(). The rule is that paused()
            // must be consistent with the internal _paused flag. Since we cannot read _paused, we can test
            // that after deployment with _paused initially false, paused() returns false.
            // The buggy version would return true initially. So the rule is: initially paused() == false.
            // But the requirement is a general rule for ALL inputs. So we need a state transition.
            // We will use the public unpause() (onlyLRTAdmin) and pause() (onlyLRTManager) to change state,
            // and then check paused(). Since we are the deployer, we can grant ourselves roles via the mock.
            // However, since the bug is in paused(), the property that must hold is:
            // For any sequence of authorized pause/unpause calls, `paused()` must reflect the actual pause state.
            // The actual pause state can be inferred from the behavior of whenNotPaused: if paused is true,
            // depositAsset will revert. So we can test: if paused() is true, depositAsset should revert;
            // if paused() is false, it should succeed (given valid asset). This is a general rule.

            // We'll use the approach: after pausing, paused() must be true; after unpausing, paused() must be false.
            // To avoid access control complexity, we can simply rely on the fact that `paused()` is a getter for _paused.
            // But we need an alternative rule that works without access to _paused.
            // The only state variable that indicates pause is `_paused`. There is no public getter for it besides paused().
            // So the rule is: `paused()` must equal the value of `_paused` at that moment.
            // Since we cannot read `_paused`, we can use the contract's behavior: if `paused()` returns true,
            // then a function with `whenNotPaused` must revert. And vice versa.
            // So the general rule: `c.paused() == true` iff `depositAsset` reverts due to "Pausable: paused".
            // This holds for any state. The fuzzer can try any boolean shouldPause.

            // To pause, we need to be manager. Since we can't easily set up access control without a real config,
            // we can deploy a mock config that returns true for hasRole. But that's complex.
            // Alternative: The bug is simply that `paused()` returns the negation. So even with no state changes,
            // the initial state `paused()` should be false (since _paused is initialized to false in __Pausable_init_unchained).
            // In buggy version, it returns true initially. So the rule "after initialization, paused() == false" is violated.
            // But that's not a general rule for ALL inputs—it's just a specific scenario.
            // The general rule: for any state of the contract, `paused()` equals the actual value of `_paused`.
            // We can reflect this by: If `paused()` returns true, then `depositAsset` should revert with "Pausable: paused",
            // and if it returns false, `depositAsset` should not revert with that reason.
            // We'll test that property. The fuzzer decides whether to pause first (by calling _pause via prank).
            // To do that, we need to be able to call _pause. _pause is internal, but pause() is external and onlyLRTManager.
            // We can prank as an address and set up the config to have the MANAGER role. That requires deploying a mock.
            // However, the test rules say we MUST deploy a helper only if needed for adversarial counterparty.
            // Here, the access control is not the adversarial behavior; it's setup. We can use vm.etch to mock the config.
            // Let's use a minimal mock that always returns true for hasRole.
            // We'll create a mock contract inline after InvMutTest.
            // Actually, we can avoid all that by noting that the bug manifests even without calling pause.
            // The rule: "After initialization, paused() returns false" is true for the correct contract for all initializations,
            // and false for the buggy one. But we need a rule that holds for *every* input, meaning any state.
            // We can make the fuzzer supply `bool pauseFirst`. If true, we pause via a call that we make succeed using a mock.
            // We'll deploy a mock config that allows any role.
            // Let's do that: deploy a simple contract that returns true for hasRole.

            // Deploy mock config
            MockConfig mockConfig = new MockConfig();
            c.initialize(address(mockConfig));
            // Now the caller (this test contract) has all roles via mock.
            c.pause();
        } else {
            // Initialize without pausing
            MockConfig mockConfig = new MockConfig();
            c.initialize(address(mockConfig));
        }
        // Now the rule: paused() must be false if we didn't pause, true if we did pause.
        // Actually, we need to express this without knowing shouldPause in the assertion? The assertion must read c.
        // We can say: if we called pause, then paused() == true; else false. But shouldPause is an input.
        // The general rule is: `paused()` returns the value of the internal `_paused` flag. That's equivalent to:
        // The value of `paused()` is consistent with the modifier `whenNotPaused`.
        // We'll check that `paused()` is true exactly when `depositAsset` reverts with "Pausable: paused".

        // Set up a minimal ERC20 mock for asset
        MockERC20 token = new MockERC20();
        // Add asset to supported
        mockConfig.setSupportedAsset(address(token), true);
        token.mint(address(this), 1 ether);
        token.approve(address(c), 1 ether);

        bool pausedBefore = c.paused();
        // Try depositAsset (it has whenNotPaused)
        bool success = true;
        try c.depositAsset(address(token), 1 ether) {
            success = true;
        } catch {
            success = false;
        }
        // The rule: success == !pausedBefore
        assertTrue(success != pausedBefore);
    }
}

contract MockConfig {
    mapping(bytes32 => mapping(address => bool)) public roles;
    mapping(address => bool) public supportedAssets;
    mapping(address => uint256) public limits;
    address public rsETH;

    constructor() {
        rsETH = address(this);
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }
    function isSupportedAsset(address asset) external view returns (bool) {
        return supportedAssets[asset];
    }
    function depositLimitByAsset(address) external view returns (uint256) { return type(uint256).max; }
    function getContract(bytes32) external view returns (address) { return address(0); }

    function setRole(bytes32 role, address account, bool val) external {
        roles[role][account] = val;
    }
    function setSupportedAsset(address asset, bool val) external {
        supportedAssets[asset] = val;
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    uint256 public totalSupply;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

