pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); c.initialize(address(this)); }
    function testFuzz_property(address admin) public {
        vm.assume(admin != address(0) && admin != address(this));
        // grant DEFAULT_ADMIN_ROLE to admin for pause/unpause
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;
        vm.prank(address(this));
        IAccessControl(address(c.lrtConfig())).grantRole(DEFAULT_ADMIN_ROLE, admin);

        // Ensure paused state is initially false
        bool beforePause = c.paused();

        // call pause and then check paused()
        vm.prank(admin);
        c.pause();
        bool afterPause = c.paused();

        // Assert that paused() reflects the true state after pausing (should be true)
        assertTrue(afterPause == true);
    }
}

interface IAccessControl {
    function grantRole(bytes32 role, address account) external;
}

